from fractions import Fraction as F
from math import comb
from itertools import combinations
from pathlib import Path
import json,hashlib

def choose(n,k):return comb(n,k) if n>=k else 0
def mixed(t,u,m,n):
 N=t+u+m;d=choose(N,n)
 return 1-F(choose(N-t,n),d)-F(choose(N-u,n),d)+F(choose(m,n),d)
def panel(groups,k,n):
 absence=F(0)
 for selected in combinations(groups,k):
  q=F(1)
  for t,u,m in selected:q*=1-mixed(t,u,m,n)
  absence+=q
 return 1-absence/comb(len(groups),k)
def ratio(p):return {'numerator':str(p.numerator),'denominator':str(p.denominator),'display_approximation':float(p)}
# Exhaustive independent check of the inclusion-exclusion formula on small toy populations.
checked=0
for t in range(5):
 for u in range(5):
  for m in range(4):
   rows='T'*t+'U'*u+'M'*m
   for n in [2,4]:
    if len(rows)<n:continue
    tuples=list(combinations(rows,n));direct=F(sum('T' in s and 'U' in s for s in tuples),len(tuples))
    assert mixed(t,u,m,n)==direct;checked+=1
scenarios={'homogeneous_sparse_controls':[(70,10,20)]*4,'homogeneous_balanced':[(40,40,20)]*4,'one_rare_mixed_stratum':[(10,90,0)]+[(100,0,0)]*3,'no_controls':[(80,0,20)]*4}
result={'decision':'D100','provenance':'exact hypothetical design sensitivity, not empirical prevalence or predictive validation','cases_exhaustively_checked':checked,'fixed_total_members':8,'pair_inclusion_ratio_for_N_at_least_4':ratio(F(2*4*3,4*2*1)),'single_member_inclusion_ratio_for_N_at_least_4':ratio(F(2*4,4*2)),'scenarios':{name:{'groups_T_U_M':groups,'four_strata_two_members':ratio(panel(groups,4,2)),'two_strata_four_members':ratio(panel(groups,2,4))} for name,groups in scenarios.items()},'limitations':['Not inferred from D097 or pooled old pilots.','Finite mixed-stratum probability is not probability of passing fresh origins, targets and actual matched role assignment.','Greater within-stratum support sacrifices breadth; clustered unavailable data can worsen the six-of-eight gate.','No negative candidate can be manufactured in a population containing none.','For strata smaller than4, saturation changes marginal probabilities; exact sampler weights remain authoritative.']}
result['script']={'source':Path(__file__).read_text(),'sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
Path('docs/implementation/PHASE_03_CONTROL_DESIGN_SENSITIVITY.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k!='script'},indent=2))
